package com.stockflow.inventory; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class StockBalanceTest{@Test void preventsOversell(){var b=new StockBalance(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"-");b.receive(BigDecimal.TEN);assertThrows(IllegalStateException.class,()->b.issue(new BigDecimal("10.000001")));}@Test void computesAvailable(){var b=new StockBalance(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"-");b.receive(new BigDecimal("2.5"));assertEquals(new BigDecimal("2.500000"),b.available().setScale(6));}}